ZO_CreateStringId("ITR_ADD_EXI", "[ItemTracker] Tracker already exists!")
ZO_CreateStringId("ITR_ADD_INF", "[ItemTracker] To add tracker:\nRMB on item → 'Link in Chat' → /itr_add [link]")

ZO_CreateStringId("ITR_DEL", "[ItemTracker] Tracker deleted!")
ZO_CreateStringId("ITR_DEL_NOT", "[ItemTracker] Tracker not found!")
